class ModelNew(nn.Module):
    """
    BatchNorm2d implemented with a custom PTX kernel launched via the CUDA driver API.
    """
    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.eps = eps
        self.momentum = momentum
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer('running_mean', torch.zeros(num_features))
        self.register_buffer('running_var', torch.ones(num_features))
        self.register_buffer('num_batches_tracked', torch.tensor(0, dtype=torch.long))
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, 'Input must be a CUDA tensor'
        x = x.contiguous().to(torch.float32)
        N, C, H, W = x.shape
        device = x.device
        if self.training:
            sum_t = torch.zeros(C, dtype=torch.float64, device=device)
            sumsq_t = torch.zeros(C, dtype=torch.float64, device=device)
            _launch_reduce(x, sum_t, sumsq_t, N, C, H, W)
            torch.cuda.synchronize()
            count = N * H * W
            mean64 = sum_t / count
            var_biased64 = sumsq_t / count - mean64 * mean64
            var_biased64 = torch.clamp(var_biased64, min=0.0)
            mean = mean64.to(torch.float32).contiguous()
            var_biased = var_biased64.to(torch.float32)
            with torch.no_grad():
                if count > 1:
                    var_unbiased = (var_biased64 * (count / (count - 1))).to(torch.float32)
                else:
                    var_unbiased = var_biased
                self.running_mean.mul_(1 - self.momentum).add_(mean * self.momentum)
                self.running_var.mul_(1 - self.momentum).add_(var_unbiased * self.momentum)
                self.num_batches_tracked += 1
            invstd = (1.0 / torch.sqrt(var_biased + self.eps)).contiguous()
        else:
            mean = self.running_mean.to(torch.float32).contiguous()
            invstd = (1.0 / torch.sqrt(self.running_var.to(torch.float32) + self.eps)).contiguous()
        gamma = self.weight.to(torch.float32).contiguous()
        beta = self.bias.to(torch.float32).contiguous()
        y = torch.empty_like(x)
        _launch_normalize(x, y, mean, invstd, gamma, beta, N, C, H, W)
        torch.cuda.synchronize()
        return y
